ry. Subscribe to DW Documentary: https://www.youtube.com/channel/UCW39zufHfsuGgpLviKh297Q?sub_confirmation=1# For more documentaries visit: http://www.dw.com/en/tv/docfilm/s-3610 Instagram https://www.instagram.com/dwdocumentary/ Facebook: https://www.facebook.com/dw.stories DW netiquette policy: http://www.dw.com/en/dws-netiquette-policy/a-5300954","thumbnail":"https://i.ytimg.com/vi/qwNVNE83Udo/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2019-02-07T19:00:03Z","viewCount":1117342,"durationSeconds":2546,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
